// --------------------------------------------------------------------------
// RACER: the ARCADE physics' engine (R82, the "32X feel"; docs/ports/kestrel_racing/FEEL.md). Our own
// longitudinal model, fitted to the 32X's measured behaviour (feel_params.zig, generated by
// tools/racer/feel.py, whose integer twin is this file's oracle): per tick, the forward speed s moves by
//   thr * (net(s) + drag(s)) - drag(s) - off * K_OFF * s^2 - brake * BRAKE   (no deceleration past MAX_DEC)
// with net / drag piecewise-linear curves of a few control points, pedals that ramp in, and the off-road
// drag halved with one or two wheels off. The CLASSIC physics (freds72's, car.zig) is untouched: `model`
// picks one per race (the options screen's PHYSICS row, key T); the reference's recorded drivers always
// run CLASSIC (game.zig). Integer only. No ZigOS import.
// --------------------------------------------------------------------------
const std = @import("std");
const params = @import("feel_params.zig");

pub const Model = enum(u8) { classic, arcade };
pub const NAMES = [_][]const u8{ "CLASSIC", "ARCADE" };
/// The PHYSICS option (RAM only, as every option): ARCADE by default.
pub var model: Model = .arcade;
/// The harness' --break feel (key I): the drag doubled, which every arcade race's result shows.
pub var break_feel: bool = false;
/// The CAR CLASS option: an index into params.CLASSES (FORMULA by default).
pub var class: u8 = 0;

pub const PEDAL: i32 = 32; // a pedal's ramp a tick, of 256: feel.py's PEDAL
pub const OFF_NONE: u2 = 0;
pub const OFF_HALF: u2 = 1; // one or two wheels off the asphalt
pub const OFF_FULL: u2 = 2; // three or four
pub const MAX_RPM: i32 = 39322; // sfx.zig's engine range (classic's max_rpm, 0.6)
const GEARS = [_]i32{ 18, 32, 47, 62, 78, 101 }; // our gearbox for the engine note: shift points, % of top (cosmetic)

pub fn block() *const params.Block {
    return &params.CLASSES[class];
}

/// The curve at speed v (Q16 units a tick), Q24 a tick: flat beyond its ends.
pub fn at(comptime n: usize, s: [n]i32, a: [n]i32, m: [n - 1]i32, v: i32) i32 {
    if (v <= s[0]) return a[0];
    inline for (0..n - 1) |i| {
        if (v < s[i + 1]) return a[i] + @as(i32, @intCast((@as(i64, v - s[i]) * m[i]) >> 16));
    }
    return a[n - 1];
}

fn net(b: *const params.Block, v: i32) i32 {
    return at(5, b.net.s, b.net.a, b.net.m, v);
}

fn drag(b: *const params.Block, v: i32) i32 {
    return at(3, b.drag.s, b.drag.a, b.drag.m, v);
}

/// One tick of forward speed (Q16): feel.py's `step` bit for bit.
pub fn speed(b: *const params.Block, s: i32, thr: i32, brake: i32, off: u2) i32 {
    const d = drag(b, s);
    const tract = (if (s < b.top) net(b, s) else 0) + d;
    var a: i64 = ((@as(i64, tract) * thr) >> 8) - (d << @intFromBool(break_feel)) - ((@as(i64, b.brake) * brake) >> 8);
    if (off != OFF_NONE) {
        const sq = (@as(i64, s) * s) >> 16;
        a -= ((sq * b.k_off) >> 16) >> @intFromBool(off == OFF_HALF);
    }
    a = @max(a, -@as(i64, b.max_dec));
    const n = @as(i64, s) + ((a + 128) >> 8);
    return @intCast(std.math.clamp(n, 0, @max(s, b.top)));
}

pub fn pedal(p: i32, held: bool) i32 {
    return if (held) @min(p + PEDAL, 256) else @max(p - PEDAL, 0);
}

/// A car's arcade state: its pedals and how many wheels are off the asphalt (wall.zig counts them).
pub const Engine = struct {
    thr: i32 = 0,
    brake: i32 = 0,
    off: u2 = OFF_NONE,

    pub fn press(self: *Engine, accel: bool, brk: bool) void {
        self.thr = pedal(self.thr, accel and !brk);
        self.brake = pedal(self.brake, brk);
    }
};

/// The engine note's rpm (sfx.zig's range) at speed s: our gearbox, the revs rising through each gear.
pub fn rpm(b: *const params.Block, s: i32) i32 {
    var lo: i32 = 0;
    for (GEARS) |g| {
        const hi = @divTrunc(b.top * g, 100);
        if (s < hi) {
            const frac = @divTrunc(@as(i64, s - lo) << 16, hi - lo); // Q16 within the gear
            return @intCast(@divTrunc(@as(i64, MAX_RPM) * ((3 << 16) + frac * 7), 10 << 16)); // 30% .. 100%
        }
        lo = hi;
    }
    return MAX_RPM;
}
